iginal replica count restored'}, 'rollback': {'trigger': 'scaling fails', 'action': 'verify current replicas', 'safety_guard': 'ensure service remains stable'}, 'risk_class': 'high', 'blast_radius': 'medium'}, {'id': 'generate-report', 'description': 'Generate a chaos report with time-to-recover measurement', 'action': 'create_report', 'target': 'chaos-report', 'parallel_group': None, 'preconditions': [{'description': 'rollback completed', 'fact': 'rollback_successful', 'established_by': 'rollback-replicas', 'probe': None}], 'verification': None, 'rollback': None, 'risk_class': 'medium', 'blast_radius': 'medium'}], 'dependencies': [{'from_task': 'inject-chaos', 'to_task': 'observe-recovery', 'kind': 'hard', 'reason': ''}, {'from_task': 'observe-recovery', 'to_task': 'rollback-replicas', 'kind': 'hard', 'reason': ''}, {'from_task': 'rollback-replicas', 'to_task': 'generate-report', 'kind': 'hard', 'reason': ''}], 'branches': []}

